from collections import defaultdict, deque

def findOrder(dict, N, K):
    # Create a graph
    graph = defaultdict(list)

    # Create an indegree array
    indegree = [0] * K

    # Build the graph
    for i in range(N - 1):
        word1 = dict[i]
        word2 = dict[i + 1]
        min_len = min(len(word1), len(word2))

        for j in range(min_len):
            if word1[j] != word2[j]:
                graph[ord(word1[j]) - ord('a')].append(ord(word2[j]) - ord('a'))
                indegree[ord(word2[j]) - ord('a')] += 1
                break

    # Perform topological sort using Kahn's algorithm
    queue = deque()
    for i in range(K):
        if indegree[i] == 0:
            queue.append(i)

    order = []
    while queue:
        node = queue.popleft()
        order.append(chr(node + ord('a')))

        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # If the order has all K characters, return it
    if len(order) == K:
        return ''.join(order)
    else:
        return ""

# Example usage:
# N = 5, K = 4
# dict = ["baa", "abcd", "abca", "cab", "cad"]
